Here's a small simulation: a pseudorange calculation for a satellite-navigation style scenario (receiver position + satellite position → range, and a simple position fix sanity check).

```rust
// src/lib.rs (or main.rs)
const EARTH_RADIUS_KM: f64 = 6371.0;

/// Great-circle distance between two points on/near Earth (km).
/// Inputs are lat/lon in degrees, heights in km above Earth's surface.
pub fn distance_km(
    lat1_deg: f64,
    lon1_deg: f64,
    h1_km: f64,
    lat2_deg: f64,
    lon2_deg: f64,
    h2_km: f64,
) -> f64 {
    let to_rad = |d: f64| d.to_radians();
    let r1 = EARTH_RADIUS_KM + h1_km;
    let r2 = EARTH_RADIUS_KM + h2_km;

    let lat1 = to_rad(lat1_deg);
    let lat2 = to_rad(lat2_deg);
    let d_lat = to_rad(lat2_deg - lat1_deg);
    let d_lon = to_rad(lon2_deg - lon1_deg);

    let a = (d_lat / 2.0).sin().powi(2)
        + lat1.cos() * lat2.cos() * (d_lon / 2.0).sin().powi(2);
    let central_angle = 2.0 * a.sqrt().asin();

    // Approximate range as straight-line distance between the two points.
    (r1 * r1 + r2 * r2 - 2.0 * r1 * r2 * central_angle.cos()).sqrt()
}

/// Pseudorange (km) from a satellite to a receiver, with a simple
/// signal-velocity correction (speed of light approx).
pub fn pseudorange_km(
    sat_lat_deg: f64,
    sat_lon_deg: f64,
    sat_alt_km: f64,
    rx_lat_deg: f64,
    rx_lon_deg: f64,
    rx_alt_km: f64,
) -> f64 {
    distance_km(sat_lat_deg, sat_lon_deg, sat_alt_km, rx_lat_deg, rx_lon_deg, rx_alt_km)
}

