from enum import Enum
from typing import List


class TeaType(Enum):
    GREEN = "green"
    BLACK = "black"
    WHITE = "white"
    OOLONG = "oolong"


@dataclass
class TeaPot:
    capacity_ml: int = 250
    current_ml: int = 0

    def pour(self, amount_ml: int):
        if amount_ml > self.current_ml:
            raise ValueError("Not enough tea in pot")
        self.current_ml -= amount_ml
        return amount_ml

    def fill(self, amount_ml: int):
        if self.current_ml + amount_ml > self.capacity_ml:
            raise ValueError("Pot would overflow")
        self.current_ml += amount_ml


@dataclass
class TeaSet:
    tea_type: TeaType
    pot: TeaPot = field(default_factory=TeaPot)

    def prepare(self, amount_ml: int):
        self.pot.fill(amount_ml)

    def serve(self, guest_count: int, ml_per_guest: int = 60):
        needed = guest_count * ml_per_guest
        if needed > self.pot.current_ml:
            raise ValueError("Not enough tea for all guests")
        self.pot.current_ml -= needed
        return needed


