struct Lighthouse {
    lamp_on: bool,
    battery_hours: u32,
    crew: u32,
    fog_level: u8, // 0 = clear, 10 = thick fog
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum TickOutcome {
    LampOn,
    LampOffNoCrew,
    LampOffNoBattery,
    Recharged,
}

impl Lighthouse {
    fn new(battery_hours: u32, crew: u32, fog_level: u8) -> Self {
        Self {
            lamp_on: false,
            battery_hours,
            crew,
            fog_level: fog_level.min(10),
        }
    }

    fn visibility(&self) -> u8 {
        // Visibility drops as fog rises; a working lamp helps a bit.
        let base = 10_u8.saturating_sub(self.fog_level);
        if self.lamp_on {
            base.saturating_add(2).min(10)
        } else {
            base
        }
    }

    fn tick(&mut self) -> TickOutcome {
        if self.crew == 0 {
            self.lamp_on = false;
            return TickOutcome::LampOffNoCrew;
        }

        if self.battery_hours == 0 {
            self.lamp_on = false;
            return TickOutcome::LampOffNoBattery;
        }

        self.lamp_on = true;
        self.battery_hours -= 1;
        TickOutcome::LampOn
    }

    fn recharge_full(&mut self) {
        self.battery_hours = 100;
        self.lamp_on = false;
    }
}

