from datetime import datetime

class Volcano:
    """A simple model of a volcano."""

    def __init__(self, name, height_m=1000, magma_level=50.0):
        if height_m <= 0:
            raise ValueError("height must be positive")
        if not 0 <= magma_level <= 100:
            raise ValueError("magma_level must be between 0 and 100")
        self.name = name
        self.height_m = height_m
        self.magma_level = magma_level
        self.eruptions = 0
        self.history = []  # list of (timestamp, event)

    def add_magma(self, amount):
        self.magma_level = min(100.0, self.magma_level + amount)
        self._log("magma added")

    def cool(self, amount):
        self.magma_level = max(0.0, self.magma_level - amount)
        self._log("cooled")

    def activity(self):
        if self.magma_level >= 80:
            return "critical"
        if self.magma_level >= 50:
            return "active"
        if self.magma_level > 0:
            return "dormant"
        return "extinct"

    def erupt(self):
        if self.magma_level < 50:
            return False  # not enough magma to erupt
        self.eruptions += 1
        self.magma_level = max(0.0, self.magma_level - 40)
        self._log("eruption")
        return True

    def _log(self, event):
        self.history.append((datetime.now(), event))
