fn simulate_tick(state: &mut ReefState, water_temp_c: f64) {
    const LOWER_LIMIT: f64 = 20.0;
    const UPPER_LIMIT: f64 = 29.0;

    if water_temp_c < LOWER_LIMIT || water_temp_c > UPPER_LIMIT {
        // Stressful conditions: some corals bleach
        let bleached = state.coral_count / 10;
        state.coral_count -= bleached;
        state.bleached_count += bleached;
    } else {
        // Healthy conditions: corals grow and some bleached corals recover
        let growth = (state.coral_count / 20).max(1);
        state.coral_count += growth;

        let recovered = (state.bleached_count / 4).max(if state.bleached_count > 0 { 1 } else { 0 });
        state.bleached_count -= recovered;
        state.coral_count += recovered;
    }
}

fn simulate(initial: usize, days: u32, temps: &[f64]) -> ReefState {
    let mut state = ReefState {
        coral_count: initial,
        bleached_count: 0,
